export interface DailyQuote {
  id: number;
  de: string;
  en: string;
  es: string;
  author: string;
}

export const dailyQuotes: DailyQuote[] = [
  { id: 1, de: "Der beste Zeitpunkt, einen Baum zu pflanzen, war vor zwanzig Jahren. Der zweitbeste Zeitpunkt ist jetzt.", en: "The best time to plant a tree was twenty years ago. The second best time is now.", es: "El mejor momento para plantar un árbol fue hace veinte años. El segundo mejor momento es ahora.", author: "Chinesisches Sprichwort" },
  { id: 2, de: "Du musst der Wandel sein, den du dir für die Welt wünschst.", en: "Be the change you wish to see in the world.", es: "Sé el cambio que deseas ver en el mundo.", author: "Mahatma Gandhi" },
  { id: 3, de: "Ein langer Weg beginnt mit dem ersten Schritt.", en: "A journey of a thousand miles begins with a single step.", es: "Un viaje de mil millas comienza con un solo paso.", author: "Laozi" },
  { id: 4, de: "Wir sind, was wir wiederholt tun. Hervorragendes zu leisten ist daher keine Handlung, sondern eine Gewohnheit.", en: "We are what we repeatedly do. Excellence, then, is not an act, but a habit.", es: "Somos lo que hacemos repetidamente. La excelencia, entonces, no es un acto sino un hábito.", author: "Aristoteles" },
  { id: 5, de: "Kümmere dich um deinen Körper. Es ist der einzige Ort, an dem du leben musst.", en: "Take care of your body. It's the only place you have to live.", es: "Cuida tu cuerpo. Es el único lugar en el que tienes que vivir.", author: "Jim Rohn" },
  { id: 6, de: "Das Geheimnis des Vorankommens ist, anzufangen.", en: "The secret of getting ahead is getting started.", es: "El secreto para avanzar es comenzar.", author: "Mark Twain" },
  { id: 7, de: "Disziplin ist die Brücke zwischen Zielen und Leistung.", en: "Discipline is the bridge between goals and accomplishment.", es: "La disciplina es el puente entre las metas y los logros.", author: "Jim Rohn" },
  { id: 8, de: "Tue jeden Tag etwas, das dich der Person näher bringt, die du sein möchtest.", en: "Do something every day that brings you closer to the person you want to be.", es: "Haz algo cada día que te acerque a la persona que quieres ser.", author: "Unbekannt" },
  { id: 9, de: "Der Mensch leidet viel öfter in der Vorstellung als in der Wirklichkeit.", en: "We suffer more in imagination than in reality.", es: "Sufrimos más en la imaginación que en la realidad.", author: "Seneca" },
  { id: 10, de: "Nicht weil es schwer ist, wagen wir es nicht – weil wir es nicht wagen, ist es schwer.", en: "It is not because things are difficult that we do not dare; it is because we do not dare that things are difficult.", es: "No es porque las cosas sean difíciles que no nos atrevemos; es porque no nos atrevemos que las cosas son difíciles.", author: "Seneca" },
  { id: 11, de: "Wer nicht jeden Tag etwas für seine Gesundheit aufbringt, muss eines Tages sehr viel Zeit für Krankheit opfern.", en: "He who does not find time for health will sooner or later have to find time for illness.", es: "Quien no dedica tiempo a su salud, tarde o temprano tendrá que dedicar tiempo a la enfermedad.", author: "Sebastian Kneipp" },
  { id: 12, de: "Fange an, wo du bist. Nutze, was du hast. Tue, was du kannst.", en: "Start where you are. Use what you have. Do what you can.", es: "Comienza donde estás. Usa lo que tienes. Haz lo que puedas.", author: "Arthur Ashe" },
  { id: 13, de: "Das Schwierige an einer täglichen Übung ist, sie täglich zu machen.", en: "The hard part about a daily practice is doing it daily.", es: "Lo difícil de una práctica diaria es hacerla a diario.", author: "Robin Sharma" },
  { id: 14, de: "Kleine Handlungen, täglich wiederholt, erzeugen außerordentliche Ergebnisse.", en: "Small deeds done are better than great deeds planned.", es: "Las pequeñas acciones, repetidas diariamente, generan resultados extraordinarios.", author: "Og Mandino" },
  { id: 15, de: "Man muss das Unmögliche versuchen, um das Mögliche zu erreichen.", en: "One must try the impossible to achieve the possible.", es: "Hay que intentar lo imposible para lograr lo posible.", author: "Hermann Hesse" },
  { id: 16, de: "Lebe so, als wärst du bereits die Person, die du sein möchtest.", en: "Act as if you already are the person you want to become.", es: "Vive como si ya fueras la persona que quieres ser.", author: "Epiktet" },
  { id: 17, de: "Jeder Experte war einmal ein Anfänger.", en: "Every expert was once a beginner.", es: "Todo experto fue una vez un principiante.", author: "Helen Hayes" },
  { id: 18, de: "Die Qualität deines Lebens ist die Qualität deiner Gewohnheiten.", en: "The quality of your life is the quality of your habits.", es: "La calidad de tu vida es la calidad de tus hábitos.", author: "Unbekannt" },
  { id: 19, de: "Tue das Schwierige zuerst. Das Leichte erledigt sich von selbst.", en: "Do the hard things first. The easy things take care of themselves.", es: "Haz primero lo difícil. Lo fácil se cuida solo.", author: "Dale Carnegie" },
  { id: 20, de: "Kraft wächst nicht aus körperlicher Kapazität – sie kommt aus einem unbeugsamen Willen.", en: "Strength does not come from physical capacity. It comes from an indomitable will.", es: "La fuerza no proviene de la capacidad física. Proviene de una voluntad indomable.", author: "Mahatma Gandhi" },
  { id: 21, de: "Wer aufhört, besser zu werden, hat aufgehört, gut zu sein.", en: "When you stop getting better, you stop being good.", es: "Cuando dejas de mejorar, dejas de ser bueno.", author: "Philip Rosenthal" },
  { id: 22, de: "Selbstdisziplin ist Selbstfürsorge.", en: "Self-discipline is self-care.", es: "La autodisciplina es autocuidado.", author: "Unbekannt" },
  { id: 23, de: "Der einzige Mensch, mit dem du dich vergleichen solltest, ist der, der du gestern warst.", en: "The only person you should compare yourself to is who you were yesterday.", es: "La única persona con quien debes compararte es con quien eras ayer.", author: "Unbekannt" },
  { id: 24, de: "Jeder Morgen ist eine neue Chance, dein Leben zu verändern.", en: "Every morning is a new opportunity to change your life.", es: "Cada mañana es una nueva oportunidad para cambiar tu vida.", author: "Unbekannt" },
  { id: 25, de: "Du musst nicht großartig sein, um anzufangen – aber du musst anfangen, um großartig zu werden.", en: "You don't have to be great to start, but you have to start to be great.", es: "No tienes que ser grandioso para empezar, pero tienes que empezar para ser grandioso.", author: "Zig Ziglar" },
  { id: 26, de: "Das Glück begünstigt den Vorbereiteten.", en: "Luck favors the prepared.", es: "La suerte favorece a los preparados.", author: "Louis Pasteur" },
  { id: 27, de: "Was immer du tun oder träumen kannst: Beginne es. Kühnheit trägt Genie, Macht und Zauber in sich.", en: "Whatever you can do or dream you can, begin it. Boldness has genius, power and magic in it.", es: "Lo que puedas hacer o sueñes que puedes, comienza. La audacia tiene genio, poder y magia.", author: "Johann Wolfgang von Goethe" },
  { id: 28, de: "Das Leben ist das, was passiert, während du beschäftigt bist, andere Pläne zu machen.", en: "Life is what happens while you are busy making other plans.", es: "La vida es lo que pasa mientras estás ocupado haciendo otros planes.", author: "John Lennon" },
  { id: 29, de: "Echte Veränderung ist schwer am Anfang, unordentlich in der Mitte und wunderbar am Ende.", en: "Real change is hard at first, messy in the middle, and gorgeous at the end.", es: "El verdadero cambio es duro al principio, desordenado en el medio y maravilloso al final.", author: "Robin Sharma" },
  { id: 30, de: "Vertraue dem Prozess.", en: "Trust the process.", es: "Confía en el proceso.", author: "Unbekannt" },
  { id: 31, de: "Dein Körper kann fast alles aushalten. Es ist dein Geist, den du überzeugen musst.", en: "Your body can stand almost anything. It's your mind you have to convince.", es: "Tu cuerpo puede soportar casi cualquier cosa. Es tu mente a la que tienes que convencer.", author: "Unbekannt" },
  { id: 32, de: "Schmerz ist temporär. Das Bereuen, aufgehört zu haben, dauert ewig.", en: "Pain is temporary. Quitting lasts forever.", es: "El dolor es temporal. El arrepentimiento de rendirse dura para siempre.", author: "Lance Armstrong" },
  { id: 33, de: "Eine Stunde pro Tag, bewusst eingesetzt, kann dein Leben verändern.", en: "One hour per day, invested consciously, can transform your life.", es: "Una hora al día, invertida conscientemente, puede transformar tu vida.", author: "Earl Nightingale" },
  { id: 34, de: "Beginne jeden Tag neu. Nutze jeden Tag voll.", en: "Begin each day fresh. Make the most of every day.", es: "Comienza cada día de nuevo. Aprovecha cada día al máximo.", author: "Unbekannt" },
  { id: 35, de: "Das Beste, was du für andere tun kannst, ist nicht, ihnen dein Geld zu geben, sondern dich selbst zu zeigen.", en: "The greatest good you can do for another is not just to share your riches but to reveal to him his own.", es: "El mayor bien que puedes hacer por otro no es solo compartir tus riquezas, sino revelarle las suyas.", author: "Benjamin Disraeli" },
  { id: 36, de: "Gib dir selbst die gleiche Freundlichkeit, die du einem guten Freund gibst.", en: "Give yourself the same kindness you would give a good friend.", es: "Date la misma amabilidad que le darías a un buen amigo.", author: "Unbekannt" },
  { id: 37, de: "Wer sich keine Zeit für Erholung nimmt, wird früher oder später Zeit für Krankheit finden.", en: "Those who think they have no time for exercise will sooner or later have to find time for illness.", es: "Quienes creen que no tienen tiempo para descansar, tarde o temprano tendrán que encontrar tiempo para la enfermedad.", author: "John Wanamaker" },
  { id: 38, de: "Das Leben belohnt Handeln.", en: "Life rewards action.", es: "La vida recompensa la acción.", author: "Tony Robbins" },
  { id: 39, de: "Ein Geist, der auf eine neue Idee gestoßen ist, kehrt nie zu seiner ursprünglichen Größe zurück.", en: "A mind that is stretched by a new experience can never go back to its old dimensions.", es: "Una mente que se ha expandido con una nueva idea nunca puede volver a sus dimensiones originales.", author: "Oliver Wendell Holmes" },
  { id: 40, de: "Das Einzige, was zwischen dir und deinem Ziel steht, ist die Geschichte, die du dir erzählst.", en: "The only thing standing between you and your goal is the story you tell yourself.", es: "Lo único que se interpone entre tú y tu objetivo es la historia que te cuentas.", author: "Jordan Belfort" },
  { id: 41, de: "Lebe im Augenblick. Das Heute ist alles, was wir wirklich haben.", en: "Live in the present moment. Today is all we truly have.", es: "Vive en el momento presente. El hoy es todo lo que realmente tenemos.", author: "Thich Nhat Hanh" },
  { id: 42, de: "Atme. Lass los. Und erinnere dich: Das ist alles, was du in diesem Moment tun musst.", en: "Breathe. Let go. And remind yourself that this very moment is the only one you know you have for sure.", es: "Respira. Suelta. Y recuerda: esto es todo lo que necesitas hacer en este momento.", author: "Deepak Chopra" },
  { id: 43, de: "Glück ist kein Zufall, sondern das Ergebnis von Vorbereitung und Gelegenheit.", en: "Luck is what happens when preparation meets opportunity.", es: "La suerte es lo que ocurre cuando la preparación se encuentra con la oportunidad.", author: "Seneca" },
  { id: 44, de: "Die meisten Menschen überschätzen, was sie in einem Jahr erreichen können, und unterschätzen, was sie in zehn Jahren erreichen können.", en: "Most people overestimate what they can do in one year and underestimate what they can do in ten years.", es: "La mayoría de las personas sobrestiman lo que pueden lograr en un año y subestiman lo que pueden lograr en diez años.", author: "Bill Gates" },
  { id: 45, de: "Sei streng zu dir selbst und sanft zu anderen.", en: "Be strict with yourself and gentle with others.", es: "Sé estricto contigo mismo y amable con los demás.", author: "Konfuzius" },
  { id: 46, de: "Kleine Dinge mit großer Liebe getan – das ist Heiligkeit.", en: "Not all of us can do great things. But we can do small things with great love.", es: "No todos podemos hacer grandes cosas. Pero podemos hacer pequeñas cosas con gran amor.", author: "Mutter Teresa" },
  { id: 47, de: "Tu so, als ob es unmöglich wäre zu scheitern.", en: "Act as if it were impossible to fail.", es: "Actúa como si fuera imposible fracasar.", author: "Winston Churchill" },
  { id: 48, de: "Heute ist immer der wichtigste Tag deines Lebens.", en: "Today is always the most important day of your life.", es: "Hoy es siempre el día más importante de tu vida.", author: "Unbekannt" },
  { id: 49, de: "Perfektion ist nicht das Ziel. Beständigkeit ist das Ziel.", en: "Perfection is not the goal. Consistency is the goal.", es: "La perfección no es el objetivo. La constancia es el objetivo.", author: "Unbekannt" },
  { id: 50, de: "Gewinne werden durch Geduld und Konsistenz erzielt, nicht durch Intensität.", en: "Gains are made through patience and consistency, not intensity.", es: "Las ganancias se logran mediante la paciencia y la constancia, no la intensidad.", author: "Unbekannt" },
  { id: 51, de: "Du wirst nicht das Leben deiner Träume leben, wenn du lebst, wie alle anderen.", en: "You will not live the life of your dreams if you live like everyone else.", es: "No vivirás la vida de tus sueños si vives como todos los demás.", author: "Unbekannt" },
  { id: 52, de: "Verändere deine Gedanken und du veränderst deine Welt.", en: "Change your thoughts and you change your world.", es: "Cambia tus pensamientos y cambiarás tu mundo.", author: "Norman Vincent Peale" },
  { id: 53, de: "Selbstkenntnis ist der Beginn aller Weisheit.", en: "Knowing yourself is the beginning of all wisdom.", es: "Conocerse a uno mismo es el comienzo de toda sabiduría.", author: "Aristoteles" },
  { id: 54, de: "Ein ruhiger Geist ist wichtiger als ein beschäftigter Terminkalender.", en: "A calm mind is more valuable than a busy schedule.", es: "Una mente tranquila es más valiosa que una agenda ocupada.", author: "Unbekannt" },
  { id: 55, de: "Das Ziel des Lebens ist Selbstentfaltung. Das eigene Wesen vollkommen zum Ausdruck bringen – dafür sind wir auf der Erde.", en: "The aim of life is self-development. To realise one's nature perfectly – that is what each of us is here for.", es: "El objetivo de la vida es el autodesarrollo. Realizar la propia naturaleza a la perfección: para eso estamos aquí.", author: "Oscar Wilde" },
  { id: 56, de: "Wenn du dich um dich selbst kümmerst, können alle anderen auch auf dich zählen.", en: "When you take care of yourself, everyone else can count on you too.", es: "Cuando te cuidas a ti mismo, los demás también pueden contar contigo.", author: "Unbekannt" },
  { id: 57, de: "Fortschritt, nicht Perfektion.", en: "Progress, not perfection.", es: "Progreso, no perfección.", author: "Unbekannt" },
  { id: 58, de: "Handlungen beweisen mehr als Worte. Gewohnheiten beweisen mehr als Handlungen.", en: "Actions speak louder than words. Habits speak louder than actions.", es: "Las acciones dicen más que las palabras. Los hábitos dicen más que las acciones.", author: "Unbekannt" },
  { id: 59, de: "Das Leben wird vorwärts gelebt und rückwärts verstanden.", en: "Life can only be understood backwards, but it must be lived forwards.", es: "La vida sólo puede entenderse mirando hacia atrás, pero debe vivirse mirando hacia adelante.", author: "Søren Kierkegaard" },
  { id: 60, de: "Tu das Richtige, auch wenn es schwer ist. Besonders dann, wenn es schwer ist.", en: "Do the right thing, even when it's hard. Especially when it's hard.", es: "Haz lo correcto, incluso cuando es difícil. Especialmente cuando es difícil.", author: "Unbekannt" },
  { id: 61, de: "Dinge zu wissen genügt nicht. Wir müssen es anwenden. Wollen genügt nicht. Wir müssen es tun.", en: "Knowing is not enough; we must apply. Willing is not enough; we must do.", es: "Saber no es suficiente; debemos aplicar. Querer no es suficiente; debemos actuar.", author: "Johann Wolfgang von Goethe" },
  { id: 62, de: "Die Vergangenheit kann nicht verändert werden. Die Zukunft liegt noch in deiner Hand.", en: "The past cannot be changed. The future is yet in your power.", es: "El pasado no puede cambiarse. El futuro aún está en tus manos.", author: "Unbekannt" },
  { id: 63, de: "Jede Meisterschaft beginnt mit dem Entschluss, es zu versuchen.", en: "Every mastery begins with the decision to try.", es: "Todo dominio comienza con la decisión de intentarlo.", author: "Unbekannt" },
  { id: 64, de: "Mache aus jedem Tag dein Meisterwerk.", en: "Make each day your masterpiece.", es: "Haz de cada día tu obra maestra.", author: "John Wooden" },
  { id: 65, de: "Wenn du müde bist, lerne dich auszuruhen, nicht aufzugeben.", en: "When you feel like quitting, think about why you started.", es: "Cuando estés cansado, aprende a descansar, no a rendirte.", author: "Banksy" },
  { id: 66, de: "Der Weg entsteht durch das Gehen.", en: "The path is made by walking.", es: "Se hace camino al andar.", author: "Antonio Machado" },
  { id: 67, de: "Wachstum ist schmerzhaft. Veränderung ist schmerzhaft. Aber nichts ist schmerzhafter als an einem Ort zu stecken, der nicht zu dir gehört.", en: "Growth is painful. Change is painful. But nothing is as painful as staying stuck somewhere you don't belong.", es: "Crecer duele. Cambiar duele. Pero nada duele más que quedarse atascado en un lugar donde no perteneces.", author: "Unbekannt" },
  { id: 68, de: "Nicht der Sturm macht den Kapitän. Die ruhige See auch nicht.", en: "A smooth sea never made a skilled sailor.", es: "Un mar tranquilo nunca hizo un marinero experto.", author: "Franklin D. Roosevelt" },
  { id: 69, de: "Sei der Gärtner deiner Seele.", en: "Be the gardener of your soul.", es: "Sé el jardinero de tu alma.", author: "Unbekannt" },
  { id: 70, de: "Wer sich selbst kennt, ist weise. Wer andere besiegt, ist stark. Wer sich selbst besiegt, ist mächtig.", en: "Knowing others is wisdom. Knowing yourself is enlightenment.", es: "Conocer a los demás es sabiduría. Conocerse a uno mismo es iluminación.", author: "Laozi" },
  { id: 71, de: "Deine Energie fließt dorthin, wo deine Aufmerksamkeit geht.", en: "Energy flows where attention goes.", es: "La energía fluye donde va la atención.", author: "Unbekannt" },
  { id: 72, de: "Wenn du deinen Körper nicht nutzt, verlierst du ihn.", en: "Use it or lose it.", es: "Úsalo o piérdelo.", author: "Unbekannt" },
  { id: 73, de: "Sei dankbar für das, was du hast – und du wirst mehr davon bekommen.", en: "Be grateful for what you have and you'll end up having more.", es: "Sé agradecido por lo que tienes y tendrás cada vez más.", author: "Oprah Winfrey" },
  { id: 74, de: "Jeder Tag ist eine neue Seite in deiner Geschichte. Mach sie lesenswert.", en: "Every day is a new page in your story. Make it worth reading.", es: "Cada día es una nueva página en tu historia. Hazla digna de leer.", author: "Unbekannt" },
  { id: 75, de: "Was dich nicht tötet, macht dich stärker.", en: "That which does not kill us makes us stronger.", es: "Lo que no te mata, te hace más fuerte.", author: "Friedrich Nietzsche" },
  { id: 76, de: "Die Natur eilt nicht, und doch wird alles vollbracht.", en: "Nature does not hurry, yet everything is accomplished.", es: "La naturaleza no tiene prisa y sin embargo todo se cumple.", author: "Laozi" },
  { id: 77, de: "Erfolg ist die Summe kleiner Anstrengungen, die jeden Tag wiederholt werden.", en: "Success is the sum of small efforts, repeated day in and day out.", es: "El éxito es la suma de pequeños esfuerzos repetidos día tras día.", author: "Robert Collier" },
  { id: 78, de: "Deine Gedanken werden zu Worten. Deine Worte werden zu Handlungen. Deine Handlungen werden zu Gewohnheiten. Deine Gewohnheiten werden zu deinem Charakter.", en: "Watch your thoughts, they become your words; watch your words, they become your actions; watch your actions, they become your habits; watch your habits, they become your character.", es: "Cuida tus pensamientos, se convierten en palabras; cuida tus palabras, se convierten en acciones; cuida tus acciones, se convierten en hábitos; cuida tus hábitos, se convierten en tu carácter.", author: "Unbekannt" },
  { id: 79, de: "Was du dir vorstellst, kannst du erschaffen.", en: "Imagination is the beginning of creation.", es: "Lo que imaginas, puedes crearlo.", author: "George Bernard Shaw" },
  { id: 80, de: "Ein gesunder Körper ist das Gasthaus für die Seele. Ein kranker ist ein Gefängnis.", en: "A healthy body is the guest-chamber of the soul; a sick, its prison.", es: "Un cuerpo sano es el albergue del alma; uno enfermo, su prisión.", author: "Francis Bacon" },
  { id: 81, de: "Richte deine innere Welt ein, und deine äußere wird sich anpassen.", en: "Arrange your inner world and your outer world will adjust.", es: "Ordena tu mundo interior y tu mundo exterior se ajustará.", author: "Unbekannt" },
  { id: 82, de: "Gott gebe mir die Gelassenheit, Dinge hinzunehmen, die ich nicht ändern kann, Mut, Dinge zu ändern, die ich ändern kann, und die Weisheit, das eine vom anderen zu unterscheiden.", en: "Grant me the serenity to accept the things I cannot change, courage to change the things I can, and wisdom to know the difference.", es: "Dame la serenidad para aceptar las cosas que no puedo cambiar, el valor para cambiar las que sí puedo, y la sabiduría para conocer la diferencia.", author: "Reinhold Niebuhr" },
  { id: 83, de: "Wir sind nicht das Produkt unserer Umstände. Wir sind das Produkt unserer Entscheidungen.", en: "We are not the product of our circumstances. We are the product of our decisions.", es: "No somos el producto de nuestras circunstancias. Somos el producto de nuestras decisiones.", author: "Stephen Covey" },
  { id: 84, de: "Das Größte ist nicht, nie zu fallen – sondern jedes Mal wieder aufzustehen.", en: "Our greatest glory is not in never falling, but in rising every time we fall.", es: "Nuestra mayor gloria no consiste en no caer nunca, sino en levantarnos cada vez que caemos.", author: "Konfuzius" },
  { id: 85, de: "Schlaf ist keine Schwäche. Schlaf ist Strategie.", en: "Sleep is not weakness. Sleep is strategy.", es: "Dormir no es debilidad. Dormir es estrategia.", author: "Unbekannt" },
  { id: 86, de: "Die meisten Menschen sterben mit der Musik noch in sich.", en: "Most people die with their music still in them.", es: "La mayoría de la gente muere con la música aún dentro de ellos.", author: "Oliver Wendell Holmes" },
  { id: 87, de: "Wenn du es wert bist, auf dich zu warten, ist es wert, an dir zu arbeiten.", en: "If you're worth waiting for, you're worth working for.", es: "Si merece la pena esperar por ti, merece la pena trabajar en ti.", author: "Unbekannt" },
  { id: 88, de: "Sei du selbst. Alle anderen Rollen sind schon vergeben.", en: "Be yourself; everyone else is already taken.", es: "Sé tú mismo; todos los demás puestos ya están ocupados.", author: "Oscar Wilde" },
  { id: 89, de: "Was wir lernen, indem wir etwas tun, lernen wir wirklich.", en: "What we have to learn to do, we learn by doing.", es: "Lo que tenemos que aprender a hacer, lo aprendemos haciéndolo.", author: "Aristoteles" },
  { id: 90, de: "Die Veränderung beginnt am Rand deiner Komfortzone.", en: "Change begins at the edge of your comfort zone.", es: "El cambio comienza en el límite de tu zona de confort.", author: "Roy T. Bennett" },
  { id: 91, de: "Das Leben ist kein Problem, das gelöst werden muss, sondern eine Wirklichkeit, die erlebt werden will.", en: "Life is not a problem to be solved, but a reality to be experienced.", es: "La vida no es un problema que resolver, sino una realidad que experimentar.", author: "Søren Kierkegaard" },
  { id: 92, de: "Zähle deine Segnungen, nicht deine Schwierigkeiten.", en: "Count your blessings, not your troubles.", es: "Cuenta tus bendiciones, no tus dificultades.", author: "Unbekannt" },
  { id: 93, de: "Wenn du es nicht weißt, wie du zu dem werden sollst, was du sein möchtest – fange einfach an.", en: "If you don't know how to become what you want to be – just start.", es: "Si no sabes cómo convertirte en lo que quieres ser, simplemente empieza.", author: "Unbekannt" },
  { id: 94, de: "In der Stille findet die Seele, was sie braucht.", en: "In silence the soul finds what it needs.", es: "En el silencio, el alma encuentra lo que necesita.", author: "Unbekannt" },
  { id: 95, de: "Tue jeden Tag eine Sache, die dich ängstigt.", en: "Do one thing every day that scares you.", es: "Haz cada día algo que te asuste.", author: "Eleanor Roosevelt" },
  { id: 96, de: "Gib dir selbst die Erlaubnis, gut zu sein.", en: "Give yourself permission to be good.", es: "Date permiso para ser bueno.", author: "Unbekannt" },
  { id: 97, de: "Wenn du den Atem kontrollierst, kontrollierst du den Geist.", en: "When you control the breath, you control the mind.", es: "Cuando controlas la respiración, controlas la mente.", author: "Hatha Yoga Pradipika" },
  { id: 98, de: "Die Disziplin des Schweigens ist oft wertvoller als die der Rede.", en: "The discipline of silence is often more valuable than the discipline of speech.", es: "La disciplina del silencio es a menudo más valiosa que la de la palabra.", author: "Unbekannt" },
  { id: 99, de: "Manche Menschen träumen vom Erfolg. Andere wachen früh auf und arbeiten daran.", en: "Some people dream of success, while others wake up and work for it.", es: "Algunas personas sueñan con el éxito, mientras otras se despiertan y trabajan por él.", author: "Wayne Huizenga" },
  { id: 100, de: "Sei sanft mit dir selbst. Du tust dein Bestes.", en: "Be gentle with yourself. You are doing your best.", es: "Sé amable contigo mismo. Estás haciendo lo mejor que puedes.", author: "Unbekannt" },
  { id: 101, de: "Jede Reise beginnt damit, aufzubrechen.", en: "Every journey begins with the decision to leave.", es: "Todo viaje comienza con la decisión de partir.", author: "Unbekannt" },
  { id: 102, de: "Die einzige Grenze ist die, die du in deinem Geist siehst.", en: "The only limits are the ones in your mind.", es: "Los únicos límites son los que ves en tu mente.", author: "Napoleon Hill" },
  { id: 103, de: "Tue es nicht für die Ergebnisse. Tue es für die Person, die du dabei wirst.", en: "Don't do it for the results. Do it for the person you become in the process.", es: "No lo hagas por los resultados. Hazlo por la persona en que te conviertes en el proceso.", author: "Unbekannt" },
  { id: 104, de: "Dein Leib ist dein Tempel. Halte ihn sauber und inspiriert.", en: "Your body is your temple. Keep it pure and clean for the soul to reside in.", es: "Tu cuerpo es tu templo. Mantenlo limpio e inspirado.", author: "B.K.S. Iyengar" },
  { id: 105, de: "Du kannst nicht zu einem neuen Kapitel deines Lebens gelangen, wenn du das letzte immer wieder liest.", en: "You can't start the next chapter of your life if you keep re-reading the last one.", es: "No puedes comenzar el próximo capítulo de tu vida si sigues releyendo el anterior.", author: "Unbekannt" },
  { id: 106, de: "Schlechte Tage bauen stärkere Menschen auf.", en: "Bad days build stronger people.", es: "Los días malos construyen personas más fuertes.", author: "Unbekannt" },
  { id: 107, de: "Zu wissen, was man tun muss, ist Weisheit. Es zu tun ist Tugend.", en: "To know what is right and do it is wisdom. To do it is virtue.", es: "Saber lo que hay que hacer es sabiduría. Hacerlo es virtud.", author: "Abu Bakr" },
  { id: 108, de: "Das Geheimnis der Gesundheit für Geist und Körper ist es, nicht um die Vergangenheit zu trauern, sich nicht um die Zukunft zu sorgen, sondern im jetzigen Augenblick mit Weisheit und Ernsthaftigkeit zu leben.", en: "The secret of health for both mind and body is not to mourn for the past, not to worry about the future, but to live the present moment wisely and earnestly.", es: "El secreto de la salud para la mente y el cuerpo es no lamentarse por el pasado, no preocuparse por el futuro, sino vivir el momento presente con sabiduría y sinceridad.", author: "Buddha" },
  { id: 109, de: "Die wichtigste Gewohnheit ist die, die alle anderen ermöglicht.", en: "The most important habit is the one that enables all other habits.", es: "El hábito más importante es el que permite todos los demás.", author: "Charles Duhigg" },
  { id: 110, de: "Nützlich zu sein – das ist einer der schönsten Zwecke des Lebens.", en: "Being useful is one of the most beautiful purposes of life.", es: "Ser útil es uno de los propósitos más hermosos de la vida.", author: "Unbekannt" },
  { id: 111, de: "Atme tief. Du bist hier. Das ist genug.", en: "Breathe deeply. You are here. That is enough.", es: "Respira profundamente. Estás aquí. Eso es suficiente.", author: "Thich Nhat Hanh" },
  { id: 112, de: "Aus einem ruhigen Herzen heraus handeln – das ist Kraft.", en: "Acting from a calm heart – that is true strength.", es: "Actuar desde un corazón tranquilo: eso es fuerza.", author: "Unbekannt" },
  { id: 113, de: "Mache das Richtige. Auf die richtige Art. Zur richtigen Zeit.", en: "Do the right thing. In the right way. At the right time.", es: "Haz lo correcto. De la manera correcta. En el momento correcto.", author: "Unbekannt" },
  { id: 114, de: "Was immer du bist, sei ein guter Mensch.", en: "Whatever you are, be a good one.", es: "Sea lo que seas, sé bueno en ello.", author: "Abraham Lincoln" },
  { id: 115, de: "Erholung ist ein Teil der Arbeit, nicht die Abwesenheit davon.", en: "Recovery is part of the work, not the absence of it.", es: "La recuperación es parte del trabajo, no la ausencia de él.", author: "Unbekannt" },
  { id: 116, de: "Konsistenz schlägt Intensität.", en: "Consistency beats intensity.", es: "La constancia supera a la intensidad.", author: "Unbekannt" },
  { id: 117, de: "Iss richtig, bewege dich, schlaf gut, trink Wasser. Das sind deine Superkräfte.", en: "Eat well, move your body, sleep soundly, drink water. These are your superpowers.", es: "Come bien, muévete, duerme bien, bebe agua. Esos son tus superpoderes.", author: "Unbekannt" },
  { id: 118, de: "Alles Gute braucht Zeit.", en: "All good things take time.", es: "Todas las cosas buenas requieren tiempo.", author: "Unbekannt" },
  { id: 119, de: "Tue heute, was andere nicht wollen, damit du morgen leben kannst, wie andere es nicht können.", en: "Do today what others won't, so tomorrow you can live how others can't.", es: "Haz hoy lo que otros no quieren hacer para que mañana puedas vivir como otros no pueden.", author: "Jerry Rice" },
  { id: 120, de: "Das Geheimnis des Glücks liegt nicht darin, mehr zu wollen, sondern die Fähigkeit zu entwickeln, weniger zu genießen.", en: "The secret of happiness is not in doing what one likes, but in liking what one does.", es: "El secreto de la felicidad no está en tener más, sino en desarrollar la capacidad de disfrutar con menos.", author: "Sokrates" },
  { id: 121, de: "Der Körper erreicht, was der Geist glaubt.", en: "The body achieves what the mind believes.", es: "El cuerpo logra lo que la mente cree.", author: "Unbekannt" },
  { id: 122, de: "Du hast alles, was du brauchst, um loszulegen.", en: "You have everything you need to begin.", es: "Tienes todo lo que necesitas para empezar.", author: "Unbekannt" },
  { id: 123, de: "Nichts Großes wurde je ohne Leidenschaft vollbracht.", en: "Nothing great in the world was accomplished without passion.", es: "Nada grande en el mundo se ha logrado sin pasión.", author: "Georg Wilhelm Friedrich Hegel" },
  { id: 124, de: "Tue heute Dinge, für die du morgen dankbar bist.", en: "Do things today that your future self will thank you for.", es: "Haz cosas hoy por las que mañana estarás agradecido.", author: "Unbekannt" },
  { id: 125, de: "Sei die ruhige Mitte im Chaos.", en: "Be the calm center in the chaos.", es: "Sé el centro tranquilo en el caos.", author: "Unbekannt" },
  { id: 126, de: "Fortschritt ist nicht gradlinig, aber er ist real.", en: "Progress is not linear, but it is real.", es: "El progreso no es lineal, pero es real.", author: "Unbekannt" },
  { id: 127, de: "Was du heute tust, entscheidet, wer du morgen bist.", en: "What you do today determines who you are tomorrow.", es: "Lo que haces hoy determina quién serás mañana.", author: "Unbekannt" },
  { id: 128, de: "Erkenne, dass alles sich verändert, und du wirst keinen Schmerz finden.", en: "Realize that everything connects to everything else.", es: "Reconoce que todo cambia y no encontrarás dolor.", author: "Buddha" },
  { id: 129, de: "Die Stärke der Seele wächst durch Übung.", en: "The strength of the soul grows through practice.", es: "La fuerza del alma crece con la práctica.", author: "Marcus Aurelius" },
  { id: 130, de: "Setz dich täglich mit deiner besten Version auseinander.", en: "Engage daily with your best self.", es: "Confronta diariamente con tu mejor versión.", author: "Unbekannt" },
  { id: 131, de: "Die größte Revolution unserer Generation ist die Entdeckung, dass Menschen ihr Leben verändern können, indem sie ihre innere Haltung verändern.", en: "The greatest revolution of our generation is the discovery that human beings, by changing the inner attitudes of their minds, can change the outer aspects of their lives.", es: "El mayor descubrimiento de nuestra generación es que los seres humanos pueden cambiar su vida cambiando su actitud mental.", author: "William James" },
  { id: 132, de: "Wenn der Wind der Veränderung weht, bauen manche Menschen Mauern, andere Windmühlen.", en: "When the winds of change blow, some people build walls and others build windmills.", es: "Cuando sopla el viento del cambio, algunos construyen muros y otros molinos.", author: "Chinesisches Sprichwort" },
  { id: 133, de: "Sei die Person, die du gebraucht hättest, als du jünger warst.", en: "Be the person you needed when you were younger.", es: "Sé la persona que necesitabas cuando eras más joven.", author: "Unbekannt" },
  { id: 134, de: "Nichts verändert sich, bis du dich selbst veränderst.", en: "Nothing changes until you change yourself.", es: "Nada cambia hasta que tú cambias.", author: "Unbekannt" },
  { id: 135, de: "Die Freude liegt im Tun, nicht im Ergebnis.", en: "Happiness is when what you think, what you say, and what you do are in harmony.", es: "La alegría está en el hacer, no en el resultado.", author: "Mahatma Gandhi" },
  { id: 136, de: "Jeder Schritt, den du heute gehst, ist ein Schritt, den du morgen nicht mehr gehen musst.", en: "Every step you take today is one you won't have to take tomorrow.", es: "Cada paso que das hoy es uno que no tendrás que dar mañana.", author: "Unbekannt" },
  { id: 137, de: "Lebe so, dass du keine Angst vor morgen hast.", en: "Live so that you have no fear of tomorrow.", es: "Vive de tal manera que no tengas miedo al mañana.", author: "Konfuzius" },
  { id: 138, de: "Dein Potenzial ist grenzenlos. Dein Wachstum auch.", en: "Your potential is limitless. So is your growth.", es: "Tu potencial es ilimitado. Tu crecimiento también.", author: "Unbekannt" },
  { id: 139, de: "Es gibt kein schlechtes Wetter, nur falsche Kleidung.", en: "There is no bad weather, only bad clothing.", es: "No hay mal tiempo, solo ropa inadecuada.", author: "Altes Sprichwort" },
  { id: 140, de: "Handeln ist die Antwort auf Angst.", en: "Action is the antidote to fear.", es: "La acción es el antídoto del miedo.", author: "Unbekannt" },
  { id: 141, de: "Das Beste an der Zukunft ist, dass sie jeden Tag neu beginnt.", en: "The best thing about the future is that it begins a new day each time.", es: "Lo mejor del futuro es que comienza de nuevo cada día.", author: "Henry Ford" },
  { id: 142, de: "Was du nicht misst, kannst du nicht verbessern.", en: "If you can't measure it, you can't improve it.", es: "Lo que no se mide, no se puede mejorar.", author: "Peter Drucker" },
  { id: 143, de: "Wer rastet, der rostet.", en: "He who rests, rusts.", es: "Quien descansa, se oxida.", author: "Deutsches Sprichwort" },
  { id: 144, de: "Die Seele, die sich nicht täglich übt in Güte, ist wie ein Garten ohne Pflege.", en: "A soul that does not practice kindness daily is like a garden without care.", es: "El alma que no practica la bondad diariamente es como un jardín sin cuidado.", author: "Unbekannt" },
  { id: 145, de: "Ein zufriedener Geist ist das größte Gut.", en: "A contented mind is the greatest treasure.", es: "Una mente satisfecha es el mayor tesoro.", author: "Unbekannt" },
  { id: 146, de: "Lerne jeden Tag etwas Neues. Das hält den Geist jung.", en: "Learn something new every day. It keeps the mind young.", es: "Aprende algo nuevo cada día. Eso mantiene joven la mente.", author: "Unbekannt" },
  { id: 147, de: "Komfort ist der Feind des Wachstums.", en: "Comfort is the enemy of growth.", es: "La comodidad es el enemigo del crecimiento.", author: "P.T. Barnum" },
  { id: 148, de: "Lebe nicht, um zu essen. Iss, um zu leben.", en: "Do not live to eat, but eat to live.", es: "No vivas para comer, sino come para vivir.", author: "Sokrates" },
  { id: 149, de: "Vertrauen ist gut, Handeln ist besser.", en: "Trust is good, action is better.", es: "La confianza es buena, la acción es mejor.", author: "Unbekannt" },
  { id: 150, de: "Das Geheimnis liegt nicht im Reden über Ziele, sondern im täglichen Handeln.", en: "The secret lies not in talking about goals, but in daily action.", es: "El secreto no está en hablar de metas, sino en actuar a diario.", author: "Unbekannt" },
  { id: 151, de: "Lass dein Licht leuchten, damit andere den Weg finden.", en: "Let your light shine so others can find their way.", es: "Deja brillar tu luz para que otros puedan encontrar el camino.", author: "Unbekannt" },
  { id: 152, de: "In jedem von uns steckt mehr, als wir denken.", en: "There is more in each of us than we think.", es: "En cada uno de nosotros hay más de lo que creemos.", author: "Unbekannt" },
  { id: 153, de: "Tue nichts Kleines – wenn du schon arbeitest, mach es groß.", en: "Do nothing small – if you work, make it great.", es: "No hagas nada pequeño; si trabajas, hazlo a lo grande.", author: "Andrew Carnegie" },
  { id: 154, de: "Das Jetzt ist alles, was du je haben wirst.", en: "The present moment is all you will ever have.", es: "El momento presente es todo lo que tendrás.", author: "Eckhart Tolle" },
  { id: 155, de: "Entscheide dich jeden Morgen, gut zu sein.", en: "Decide every morning to be good.", es: "Decide cada mañana ser bueno.", author: "Unbekannt" },
  { id: 156, de: "Wer sich nichts vornimmt, braucht nichts zu bereuen – aber auch nichts zu feiern.", en: "He who sets no goals has nothing to regret – but also nothing to celebrate.", es: "Quien no se propone nada no tiene nada que lamentar, pero tampoco nada que celebrar.", author: "Unbekannt" },
  { id: 157, de: "Die meisten Hindernisse existieren nur in unserem Kopf.", en: "Most obstacles exist only in our minds.", es: "La mayoría de los obstáculos existen solo en nuestra mente.", author: "Henry Ford" },
  { id: 158, de: "Das Leben ist zu kurz für schlechten Kaffee und schlechte Laune.", en: "Life is too short for bad coffee and bad moods.", es: "La vida es demasiado corta para el mal café y el mal humor.", author: "Unbekannt" },
  { id: 159, de: "Dankbarkeit öffnet die Tür zur Fülle des Lebens.", en: "Gratitude opens the door to the fullness of life.", es: "La gratitud abre la puerta a la plenitud de la vida.", author: "Melodie Beattie" },
  { id: 160, de: "Wenn du auf das schaust, was du hast im Leben, wirst du immer mehr haben. Wenn du auf das schaust, was du nicht hast, wirst du nie genug haben.", en: "If you look at what you have in life, you'll always have more. If you look at what you don't have, you'll never have enough.", es: "Si miras lo que tienes en la vida, siempre tendrás más. Si miras lo que no tienes, nunca tendrás suficiente.", author: "Oprah Winfrey" },
  { id: 161, de: "Sprich weniger. Tue mehr.", en: "Speak less. Do more.", es: "Habla menos. Haz más.", author: "Unbekannt" },
  { id: 162, de: "Der Körper ist der erste Schüler des Geistes.", en: "The body is the first student of the mind.", es: "El cuerpo es el primer alumno de la mente.", author: "Unbekannt" },
  { id: 163, de: "Wer täglich läuft, dem läuft das Glück nicht davon.", en: "He who runs daily won't let happiness run away.", es: "A quien corre a diario, la felicidad no se le escapa.", author: "Unbekannt" },
  { id: 164, de: "Vergleiche dich nur mit dir selbst von gestern.", en: "Compare yourself only to who you were yesterday.", es: "Compárate solo con quien eras ayer.", author: "Jordan B. Peterson" },
  { id: 165, de: "Kleine Schritte, täglich gegangen, führen weit.", en: "Small steps, taken daily, lead far.", es: "Pequeños pasos, dados a diario, llevan lejos.", author: "Unbekannt" },
  { id: 166, de: "Denke wie ein Weiser, aber kommuniziere in der Sprache der Menschen.", en: "Think like a wise man but communicate in the language of the people.", es: "Piensa como un sabio pero comunícate en el lenguaje de la gente.", author: "William Butler Yeats" },
  { id: 167, de: "Wenn du änderst, wie du denkst, ändert sich, was du siehst.", en: "When you change the way you look at things, the things you look at change.", es: "Cuando cambias la forma en que miras las cosas, las cosas que miras cambian.", author: "Wayne Dyer" },
  { id: 168, de: "Der stärkste Krieger ist derjenige, der seine eigenen Schwächen kennt.", en: "The strongest warrior is the one who knows his own weaknesses.", es: "El guerrero más fuerte es quien conoce sus propias debilidades.", author: "Sun Tzu" },
  { id: 169, de: "Übe Geduld. Alles Gute braucht Zeit.", en: "Practice patience. All good things take time.", es: "Practica la paciencia. Todas las cosas buenas requieren tiempo.", author: "Unbekannt" },
  { id: 170, de: "Tue das, was du liebst. Liebe das, was du tust.", en: "Do what you love. Love what you do.", es: "Haz lo que amas. Ama lo que haces.", author: "Unbekannt" },
  { id: 171, de: "Investiere täglich in dich selbst. Es ist die rentabelste Investition, die du je machen wirst.", en: "Invest in yourself daily. It is the most profitable investment you will ever make.", es: "Invierte en ti mismo diariamente. Es la inversión más rentable que jamás harás.", author: "Warren Buffett" },
  { id: 172, de: "Wähle täglich Wachstum über Komfort.", en: "Choose growth over comfort every day.", es: "Elige el crecimiento sobre la comodidad cada día.", author: "Unbekannt" },
  { id: 173, de: "Es ist nie zu spät, der Mensch zu werden, der du sein könntest.", en: "It is never too late to be what you might have been.", es: "Nunca es demasiado tarde para convertirte en lo que podrías haber sido.", author: "George Eliot" },
  { id: 174, de: "Disziplin ist die höchste Form der Liebe zu sich selbst.", en: "Discipline is the highest form of self-love.", es: "La disciplina es la forma más elevada de amor propio.", author: "Unbekannt" },
  { id: 175, de: "Finde die Freude im Tun.", en: "Find the joy in doing.", es: "Encuentra la alegría en el hacer.", author: "Unbekannt" },
  { id: 176, de: "Morgen beginnt heute.", en: "Tomorrow begins today.", es: "El mañana comienza hoy.", author: "Unbekannt" },
  { id: 177, de: "Tue jeden Tag etwas Gutes für jemanden, der es dir nicht zurückzahlen kann.", en: "Do something good every day for someone who can't repay you.", es: "Haz algo bueno cada día por alguien que no pueda devolvértelo.", author: "John Wooden" },
  { id: 178, de: "Aufmerksamkeit ist die seltenste und reinste Form der Großzügigkeit.", en: "Attention is the rarest and purest form of generosity.", es: "La atención es la forma más rara y pura de generosidad.", author: "Simone Weil" },
  { id: 179, de: "Dein Geist ist ein Garten. Deine Gedanken sind die Samen. Du kannst Blumen wachsen lassen oder Unkraut.", en: "Your mind is a garden. Your thoughts are the seeds. You can grow flowers or you can grow weeds.", es: "Tu mente es un jardín. Tus pensamientos son las semillas. Puedes cultivar flores o maleza.", author: "Unbekannt" },
  { id: 180, de: "Sei beständig. Die Welt macht Platz für Menschen, die wissen, wohin sie gehen.", en: "Be consistent. The world makes way for people who know where they are going.", es: "Sé constante. El mundo cede el paso a las personas que saben adónde van.", author: "Josiah Gilbert Holland" },
  { id: 181, de: "Nicht wer du bist hält dich auf. Es ist, wer du glaubst, nicht zu sein.", en: "It's not who you are that holds you back. It's who you think you're not.", es: "No es quién eres lo que te frena. Es quién crees que no eres.", author: "Denis Waitley" },
  { id: 182, de: "Das Geheimnis deines zukünftigen Selbst liegt in deinen heutigen Gewohnheiten.", en: "The secret to your future self lies in your habits today.", es: "El secreto de tu yo futuro está en tus hábitos de hoy.", author: "Unbekannt" },
  { id: 183, de: "Ruhe ist keine Faulheit. Manchmal ist es das Klügste, was du tun kannst.", en: "Rest is not laziness. Sometimes it is the wisest thing you can do.", es: "El descanso no es pereza. A veces es lo más inteligente que puedes hacer.", author: "Unbekannt" },
  { id: 184, de: "Wenn du mit der gleichen Energie auf deine Träume hinarbeitest wie auf dein Smartphone – bist du unaufhaltsam.", en: "If you work toward your dreams with the same energy you put into your smartphone, you'll be unstoppable.", es: "Si trabajas hacia tus sueños con la misma energía que pones en tu smartphone, serás imparable.", author: "Unbekannt" },
  { id: 185, de: "Wachstum ist unbequem, aber Stagnation ist schmerzhafter.", en: "Growth is uncomfortable, but stagnation is more painful.", es: "Crecer es incómodo, pero el estancamiento es más doloroso.", author: "Unbekannt" },
  { id: 186, de: "Das Leben fragt uns nicht, was wir gerne täten. Es fragt uns, was wir tun.", en: "Life does not ask us what we'd like to do. It asks us what we do.", es: "La vida no nos pregunta lo que nos gustaría hacer. Nos pregunta lo que hacemos.", author: "Tennessee Williams" },
  { id: 187, de: "Sei die Energie, die du in den Raum bringen möchtest.", en: "Be the energy you want to bring into the room.", es: "Sé la energía que quieres traer al espacio.", author: "Dr. Jill Bolte Taylor" },
  { id: 188, de: "Die Welt gehört dem Ausdauernden.", en: "The world belongs to the perseverant.", es: "El mundo pertenece al perseverante.", author: "Ralph Waldo Emerson" },
  { id: 189, de: "Halte den Kurs. Auch wenn es langsam geht.", en: "Stay the course. Even when it's slow.", es: "Mantén el rumbo. Incluso cuando vaya despacio.", author: "Unbekannt" },
  { id: 190, de: "Dein Körper hört, was dein Kopf sagt.", en: "Your body hears everything your mind says.", es: "Tu cuerpo escucha todo lo que dice tu mente.", author: "Unbekannt" },
  { id: 191, de: "Der Wille ist stark. Die Gewohnheit ist stärker.", en: "The will is strong. The habit is stronger.", es: "La voluntad es fuerte. El hábito es más fuerte.", author: "Unbekannt" },
  { id: 192, de: "Erfolg ist nicht das Ziel. Er ist ein Nebenprodukt guter Gewohnheiten.", en: "Success is not the goal. It is a by-product of good habits.", es: "El éxito no es el objetivo. Es un subproducto de buenos hábitos.", author: "Unbekannt" },
  { id: 193, de: "Geh heute einen Schritt weiter als gestern.", en: "Go one step further today than you did yesterday.", es: "Da hoy un paso más allá que ayer.", author: "Unbekannt" },
  { id: 194, de: "Das Innere und das Äußere sind eins. Du bist, was du denkst.", en: "The inner and the outer are one. You are what you think.", es: "Lo interior y lo exterior son uno. Eres lo que piensas.", author: "Unbekannt" },
  { id: 195, de: "Tue Gutes – jeden Tag ein bisschen.", en: "Do good – a little bit every day.", es: "Haz el bien: un poco cada día.", author: "Unbekannt" },
  { id: 196, de: "Der Morgen ist der wichtigste Teil des Tages.", en: "The morning is the most important part of the day.", es: "La mañana es la parte más importante del día.", author: "Unbekannt" },
  { id: 197, de: "Lächle. Es verändert alles.", en: "Smile. It changes everything.", es: "Sonríe. Lo cambia todo.", author: "Unbekannt" },
  { id: 198, de: "Suche den Fortschritt, nicht die Perfektion.", en: "Seek progress, not perfection.", es: "Busca el progreso, no la perfección.", author: "Unbekannt" },
  { id: 199, de: "Gesundheit ist nicht alles, aber ohne Gesundheit ist alles nichts.", en: "Health is not everything, but without health, everything is nothing.", es: "La salud no lo es todo, pero sin salud, todo es nada.", author: "Arthur Schopenhauer" },
  { id: 200, de: "Vergiss nicht zu leben, während du an deinen Zielen arbeitest.", en: "Don't forget to live while you're working toward your goals.", es: "No olvides vivir mientras trabajas por tus metas.", author: "Unbekannt" },
  { id: 201, de: "Dankbarkeit ist die gesündeste Emotion, die du jeden Tag spüren kannst.", en: "Gratitude is the healthiest emotion you can feel every day.", es: "La gratitud es la emoción más saludable que puedes sentir cada día.", author: "Unbekannt" },
  { id: 202, de: "Jeder Tag bringt eine neue Möglichkeit, besser zu werden.", en: "Every day brings a new opportunity to improve.", es: "Cada día trae una nueva oportunidad de mejorar.", author: "Unbekannt" },
  { id: 203, de: "Was auch immer heute passiert – du schaffst das.", en: "Whatever happens today – you can handle it.", es: "Pase lo que pase hoy, puedes con ello.", author: "Unbekannt" },
  { id: 204, de: "Die Wurzeln der Bildung sind bitter, aber ihre Früchte sind süß.", en: "The roots of education are bitter, but the fruit is sweet.", es: "Las raíces de la educación son amargas, pero sus frutos son dulces.", author: "Aristoteles" },
  { id: 205, de: "Übe Güte. Es ist immer die richtige Entscheidung.", en: "Practice kindness. It is always the right choice.", es: "Practica la bondad. Siempre es la decisión correcta.", author: "Unbekannt" },
  { id: 206, de: "Wer jeden Tag ein bisschen lernt, wird am Ende sehr klug sein.", en: "He who learns a little every day will end up very wise.", es: "Quien aprende un poco cada día, acabará siendo muy sabio.", author: "Unbekannt" },
  { id: 207, de: "Das Wasser höhlt den Stein nicht durch Kraft, sondern durch beständiges Tropfen.", en: "Dripping water hollows out stone not through force but through persistence.", es: "El agua horada la piedra no con la fuerza sino con la constancia.", author: "Ovid" },
  { id: 208, de: "Sei die Lösung, nicht das Problem.", en: "Be the solution, not the problem.", es: "Sé la solución, no el problema.", author: "Unbekannt" },
  { id: 209, de: "Wenn du einen Traum hast, höre nicht auf, bis er Wirklichkeit ist.", en: "If you have a dream, don't stop until it becomes reality.", es: "Si tienes un sueño, no te detengas hasta que sea realidad.", author: "Walt Disney" },
  { id: 210, de: "Du wirst durch das definiert, was du tust, wenn es zählt.", en: "You are defined by what you do when it matters.", es: "Eres definido por lo que haces cuando importa.", author: "Unbekannt" },
  { id: 211, de: "Setze klare Grenzen. Lebe mit Intention.", en: "Set clear boundaries. Live with intention.", es: "Establece límites claros. Vive con intención.", author: "Unbekannt" },
  { id: 212, de: "Das Gute daran, jeden Tag anzufangen: Du bekommst jeden Tag eine neue Chance.", en: "The good thing about starting every day: you get a new chance every day.", es: "Lo bueno de comenzar cada día: tienes una nueva oportunidad cada día.", author: "Unbekannt" },
  { id: 213, de: "Das Glück ist kein Ziel – es ist eine Art zu reisen.", en: "Happiness is not a destination – it's a way of traveling.", es: "La felicidad no es un destino, es una manera de viajar.", author: "Margaret Lee Runbeck" },
  { id: 214, de: "Der Fortschritt ist immer schwierig und selten gradlinig – aber er ist real.", en: "Progress is always difficult and rarely linear – but it is real.", es: "El progreso siempre es difícil y rara vez lineal, pero es real.", author: "Unbekannt" },
  { id: 215, de: "Stell sicher, dass dein Schlafgehen du morgen dir dankt.", en: "Make sure your going-to-sleep self thanks your waking-up self tomorrow.", es: "Asegúrate de que el tú de mañana agradezca lo que el tú de hoy hizo antes de dormir.", author: "Unbekannt" },
  { id: 216, de: "Halte inne. Atme. Dann handle.", en: "Pause. Breathe. Then act.", es: "Detente. Respira. Luego actúa.", author: "Unbekannt" },
  { id: 217, de: "Der Geist ist wie Wasser: Wenn er ruhig ist, ist er klar.", en: "The mind is like water: when it is calm, it is clear.", es: "La mente es como el agua: cuando está tranquila, está clara.", author: "Unbekannt" },
  { id: 218, de: "Niemand kann in der Vergangenheit beginnen.", en: "Nobody can start in the past.", es: "Nadie puede empezar en el pasado.", author: "Unbekannt" },
  { id: 219, de: "Nur wer sich kennt, kann sich wirklich verändern.", en: "Only those who know themselves can truly change.", es: "Solo quien se conoce a sí mismo puede cambiar de verdad.", author: "Unbekannt" },
  { id: 220, de: "Wenn du aufhörst, zu wachsen, beginnst du zu sterben.", en: "When you stop growing, you start dying.", es: "Cuando dejas de crecer, empiezas a morir.", author: "William S. Burroughs" },
  { id: 221, de: "Die Qualität deiner Fragen bestimmt die Qualität deines Lebens.", en: "The quality of your questions determines the quality of your life.", es: "La calidad de tus preguntas determina la calidad de tu vida.", author: "Tony Robbins" },
  { id: 222, de: "Dein Herz weiß den Weg. Lauf in diese Richtung.", en: "Your heart knows the way. Run in that direction.", es: "Tu corazón conoce el camino. Corre en esa dirección.", author: "Rumi" },
  { id: 223, de: "Tue das Richtige, bis es zur Gewohnheit wird.", en: "Do the right thing until it becomes a habit.", es: "Haz lo correcto hasta que se convierta en un hábito.", author: "Unbekannt" },
  { id: 224, de: "Das Fleisch ist willig, wenn der Geist klar ist.", en: "The flesh is willing when the mind is clear.", es: "La carne está dispuesta cuando la mente está clara.", author: "Unbekannt" },
  { id: 225, de: "Das Leben liebt den, der es lebt.", en: "Life loves the liver of it.", es: "La vida ama a quien la vive.", author: "Maya Angelou" },
  { id: 226, de: "Sei der Friede, den du in der Welt sehen möchtest.", en: "Be the peace you wish to see in the world.", es: "Sé la paz que deseas ver en el mundo.", author: "Thich Nhat Hanh" },
  { id: 227, de: "Die Wurzel jeder Freude ist Dankbarkeit.", en: "The root of all joy is gratitude.", es: "La raíz de toda alegría es la gratitud.", author: "David Steindl-Rast" },
  { id: 228, de: "Was du nicht liebst, verändere. Was du nicht verändern kannst, akzeptiere.", en: "What you don't love, change. What you can't change, accept.", es: "Lo que no amas, cámbialo. Lo que no puedes cambiar, acéptalo.", author: "Unbekannt" },
  { id: 229, de: "Tue deinen Körper wie ein Verbündeter, nicht wie einen Feind.", en: "Treat your body as an ally, not an enemy.", es: "Trata tu cuerpo como un aliado, no como un enemigo.", author: "Unbekannt" },
  { id: 230, de: "Jeder Moment ist ein Neuanfang.", en: "Every moment is a fresh beginning.", es: "Cada momento es un nuevo comienzo.", author: "T.S. Eliot" },
  { id: 231, de: "Der einfachste Weg, dein Leben zu verbessern: Schlaf mehr, trink mehr Wasser, beweg dich täglich.", en: "The simplest way to improve your life: sleep more, drink more water, move every day.", es: "La forma más sencilla de mejorar tu vida: duerme más, bebe más agua, muévete a diario.", author: "Unbekannt" },
  { id: 232, de: "Lass jeden Tag eine neue Seite in deinem Buch des Lebens sein.", en: "Let each day be a new page in the book of your life.", es: "Deja que cada día sea una nueva página en el libro de tu vida.", author: "Unbekannt" },
  { id: 233, de: "Wenn Dankbarkeit zur Haltung wird, wird das Leben zum Geschenk.", en: "When gratitude becomes an attitude, life becomes a gift.", es: "Cuando la gratitud se convierte en actitud, la vida se convierte en un regalo.", author: "Unbekannt" },
  { id: 234, de: "Wer den Geist trainiert, trainiert sein Leben.", en: "He who trains the mind trains his life.", es: "Quien entrena la mente, entrena su vida.", author: "Unbekannt" },
  { id: 235, de: "Die Stille zwischen den Gedanken ist das Wertvollste.", en: "The silence between thoughts is the most precious thing.", es: "El silencio entre los pensamientos es lo más valioso.", author: "Unbekannt" },
  { id: 236, de: "Suche nicht nach dem Glück. Sei das Glück.", en: "Don't search for happiness. Be the happiness.", es: "No busques la felicidad. Sé la felicidad.", author: "Unbekannt" },
  { id: 237, de: "Jede gute Tat kehrt zurück.", en: "Every good deed comes back around.", es: "Cada buena acción regresa.", author: "Unbekannt" },
  { id: 238, de: "Dein Körper ist das direkteste Feedback, das du je bekommen wirst.", en: "Your body is the most direct feedback you will ever receive.", es: "Tu cuerpo es la retroalimentación más directa que jamás recibirás.", author: "Unbekannt" },
  { id: 239, de: "Die beste Investition ist die in dein eigenes Lernen.", en: "The best investment is in your own learning.", es: "La mejor inversión es en tu propio aprendizaje.", author: "Benjamin Franklin" },
  { id: 240, de: "Beginne mit dem, was du liebst – der Rest folgt.", en: "Begin with what you love – the rest will follow.", es: "Comienza con lo que amas: el resto seguirá.", author: "Unbekannt" },
  { id: 241, de: "Wenn du gut schläfst, gut isst und dich bewegst, bist du dem Glück sehr nahe.", en: "When you sleep well, eat well, and move, you are very close to happiness.", es: "Cuando duermes bien, comes bien y te mueves, estás muy cerca de la felicidad.", author: "Unbekannt" },
  { id: 242, de: "Du bist näher an deinem Ziel als du denkst.", en: "You are closer to your goal than you think.", es: "Estás más cerca de tu objetivo de lo que crees.", author: "Unbekannt" },
  { id: 243, de: "Mach einen Schritt. Dann noch einen.", en: "Take one step. Then another.", es: "Da un paso. Luego otro.", author: "Unbekannt" },
  { id: 244, de: "Halte dir die Seele frei von Bitterkeit.", en: "Keep your soul free from bitterness.", es: "Mantén tu alma libre de amargura.", author: "Unbekannt" },
  { id: 245, de: "Das Beste, was du für andere tun kannst, ist ein gutes Beispiel zu sein.", en: "The best thing you can do for others is to be a good example.", es: "Lo mejor que puedes hacer por los demás es ser un buen ejemplo.", author: "Albert Schweitzer" },
  { id: 246, de: "Was du heute aussäst, erntest du morgen.", en: "What you sow today, you will reap tomorrow.", es: "Lo que siembras hoy, lo cosecharás mañana.", author: "Unbekannt" },
  { id: 247, de: "Glaube an die Macht kleiner Schritte.", en: "Believe in the power of small steps.", es: "Cree en el poder de los pequeños pasos.", author: "Unbekannt" },
  { id: 248, de: "Ehrlichkeit mit sich selbst ist das Fundament jeder Veränderung.", en: "Honesty with yourself is the foundation of all change.", es: "La honestidad con uno mismo es la base de todo cambio.", author: "Unbekannt" },
  { id: 249, de: "Die Seele wächst durch das Geben.", en: "The soul grows through giving.", es: "El alma crece a través del dar.", author: "Henry Drummond" },
  { id: 250, de: "Sei mutig genug, dein eigenes Leben zu führen.", en: "Be brave enough to live your own life.", es: "Sé lo suficientemente valiente para vivir tu propia vida.", author: "Unbekannt" },
  { id: 251, de: "Wenn du dir selbst treu bist, kannst du niemandem untreu sein.", en: "To thine own self be true, and it must follow, as the night the day, thou canst not then be false to any man.", es: "Si te eres fiel a ti mismo, no podrás ser desleal con nadie.", author: "William Shakespeare" },
  { id: 252, de: "Das Schweigen ist eine Quelle großer Stärke.", en: "Silence is a source of great strength.", es: "El silencio es una fuente de gran fortaleza.", author: "Laozi" },
  { id: 253, de: "Der Schlüssel ist nicht Prioritäten setzen, was in deinem Kalender steht, sondern das in deinen Kalender zu setzen, was deine Prioritäten sind.", en: "The key is not to prioritize what's on your schedule, but to schedule your priorities.", es: "La clave no es dar prioridad a lo que está en tu agenda, sino agendar tus prioridades.", author: "Stephen Covey" },
  { id: 254, de: "Wenn du gut mit dir selbst umgehst, wird alles andere leichter.", en: "When you treat yourself well, everything else becomes easier.", es: "Cuando te tratas bien a ti mismo, todo lo demás se vuelve más fácil.", author: "Unbekannt" },
  { id: 255, de: "Der gegenwärtige Moment wird immer gewesen sein.", en: "The present moment will always have been.", es: "El momento presente siempre habrá sido.", author: "Unbekannt" },
  { id: 256, de: "Lass die Natur dein Lehrer sein.", en: "Let nature be your teacher.", es: "Deja que la naturaleza sea tu maestro.", author: "William Wordsworth" },
  { id: 257, de: "Tue heute das, wovor du dich fürchtest.", en: "Do today what you fear.", es: "Haz hoy lo que temes.", author: "Unbekannt" },
  { id: 258, de: "Die Weisheit kommt, wenn man aufhört zu denken, und anfängt zu handeln.", en: "Wisdom comes when you stop thinking and start acting.", es: "La sabiduría llega cuando dejas de pensar y empiezas a actuar.", author: "Unbekannt" },
  { id: 259, de: "Entscheide dich jeden Tag, dankbar zu sein.", en: "Choose every day to be grateful.", es: "Elige cada día ser agradecido.", author: "Unbekannt" },
  { id: 260, de: "Das Schönste an einer Gewohnheit ist: Nach einer Weile tut sie sich von selbst.", en: "The beautiful thing about a habit: after a while, it does itself.", es: "Lo más hermoso de un hábito: después de un tiempo, se hace solo.", author: "Unbekannt" },
  { id: 261, de: "Wer täglich dankt, lebt reicher.", en: "He who gives daily thanks lives more richly.", es: "Quien agradece a diario vive con más riqueza.", author: "Unbekannt" },
  { id: 262, de: "Zehn Minuten Bewegung verändern deine Stimmung.", en: "Ten minutes of movement changes your mood.", es: "Diez minutos de movimiento cambian tu estado de ánimo.", author: "Unbekannt" },
  { id: 263, de: "Tu das Richtige, nicht das Einfache.", en: "Do the right thing, not the easy thing.", es: "Haz lo correcto, no lo fácil.", author: "Unbekannt" },
  { id: 264, de: "Lebe nicht auf Autopilot. Wähle bewusst.", en: "Don't live on autopilot. Choose consciously.", es: "No vivas en piloto automático. Elige conscientemente.", author: "Unbekannt" },
  { id: 265, de: "Du bist nicht deine Gedanken. Du bist der, der sie beobachtet.", en: "You are not your thoughts. You are the one who observes them.", es: "No eres tus pensamientos. Eres quien los observa.", author: "Eckhart Tolle" },
  { id: 266, de: "Tue jeden Tag eine Sache, die dich deinem besten Selbst näherbringt.", en: "Do one thing every day that brings you closer to your best self.", es: "Haz cada día algo que te acerque a tu mejor versión.", author: "Unbekannt" },
  { id: 267, de: "Das Herz kennt Wege, die der Verstand nicht versteht.", en: "The heart has reasons that reason cannot know.", es: "El corazón conoce caminos que la razón no comprende.", author: "Blaise Pascal" },
  { id: 268, de: "Setze dir ein Ziel, das größer ist als deine Angst.", en: "Set a goal bigger than your fear.", es: "Establece una meta más grande que tu miedo.", author: "Unbekannt" },
  { id: 269, de: "Der Mensch ist das Tier, das Gewohnheiten braucht.", en: "Man is the creature of habit.", es: "El hombre es la criatura del hábito.", author: "William James" },
  { id: 270, de: "Die größten Abenteuer beginnen damit, die erste Seite aufzuschlagen.", en: "The greatest adventures begin by turning the first page.", es: "Las mayores aventuras comienzan abriendo la primera página.", author: "Unbekannt" },
  { id: 271, de: "Der Geist formt den Körper, und der Körper formt den Geist.", en: "The mind shapes the body, and the body shapes the mind.", es: "La mente forma el cuerpo, y el cuerpo forma la mente.", author: "Unbekannt" },
  { id: 272, de: "Was du heute gibst, kommt morgen zu dir zurück.", en: "What you give today comes back to you tomorrow.", es: "Lo que das hoy regresa a ti mañana.", author: "Unbekannt" },
  { id: 273, de: "Vertraue dir. Du weißt mehr als du denkst.", en: "Trust yourself. You know more than you think you do.", es: "Confía en ti. Sabes más de lo que crees.", author: "Benjamin Spock" },
  { id: 274, de: "Das Leben ist nicht das, was mit dir passiert, sondern das, was du daraus machst.", en: "Life is not what happens to you, but what you make of it.", es: "La vida no es lo que te pasa, sino lo que haces con ello.", author: "Unbekannt" },
  { id: 275, de: "Gesundheit ist kein Ziel, sondern eine Lebensweise.", en: "Health is not a goal, but a way of life.", es: "La salud no es un objetivo, sino un estilo de vida.", author: "Unbekannt" },
  { id: 276, de: "Tue das Schwierige leicht – durch Übung.", en: "Make the difficult easy – through practice.", es: "Haz lo difícil fácil: a través de la práctica.", author: "Unbekannt" },
  { id: 277, de: "Der Mut, anzufangen, ist wichtiger als die Sicherheit, zu gewinnen.", en: "The courage to begin is more important than the certainty of winning.", es: "El coraje de empezar es más importante que la certeza de ganar.", author: "Unbekannt" },
  { id: 278, de: "Du entscheidest täglich, wer du bist.", en: "You decide every day who you are.", es: "Cada día decides quién eres.", author: "Unbekannt" },
  { id: 279, de: "Das Herz, das gibt, sammelt.", en: "The heart that gives, gathers.", es: "El corazón que da, recoge.", author: "Unbekannt" },
  { id: 280, de: "Wähle täglich Dankbarkeit. Sie ist immer möglich.", en: "Choose gratitude daily. It is always possible.", es: "Elige la gratitud a diario. Siempre es posible.", author: "Unbekannt" },
  { id: 281, de: "Ein Tag voller guter Gewohnheiten ist ein guter Tag.", en: "A day full of good habits is a good day.", es: "Un día lleno de buenos hábitos es un buen día.", author: "Unbekannt" },
  { id: 282, de: "Was zählt, ist nicht, wer du warst – sondern wer du wirst.", en: "What matters is not who you were, but who you will become.", es: "Lo que importa no es quién fuiste, sino quién serás.", author: "Unbekannt" },
  { id: 283, de: "Jede Version von dir, an der du gearbeitet hast, war es wert.", en: "Every version of yourself you worked on was worth it.", es: "Cada versión de ti en la que trabajaste mereció la pena.", author: "Unbekannt" },
  { id: 284, de: "Wachse täglich ein bisschen – in Wissen, Güte oder Gesundheit.", en: "Grow a little each day – in knowledge, kindness, or health.", es: "Crece un poco cada día: en conocimiento, bondad o salud.", author: "Unbekannt" },
  { id: 285, de: "Nichts ist verloren, wenn du wieder aufstehst.", en: "Nothing is lost if you get back up.", es: "Nada está perdido si te levantas de nuevo.", author: "Unbekannt" },
  { id: 286, de: "Das Jetzt ist dein Zuhause. Kehre täglich zurück.", en: "The now is your home. Return to it daily.", es: "El ahora es tu hogar. Vuelve a él a diario.", author: "Thich Nhat Hanh" },
  { id: 287, de: "Was du nicht weißt, kannst du lernen. Was du nicht kannst, kannst du üben. Was du nicht bist, kannst du werden.", en: "What you don't know, you can learn. What you can't do, you can practice. What you're not, you can become.", es: "Lo que no sabes, puedes aprenderlo. Lo que no puedes, puedes practicarlo. Lo que no eres, puedes llegar a serlo.", author: "Unbekannt" },
  { id: 288, de: "Das Leben ist zu kurz, um unglücklich zu sein.", en: "Life is too short to be unhappy.", es: "La vida es demasiado corta para ser infeliz.", author: "Unbekannt" },
  { id: 289, de: "Wer sich selbst respektiert, respektiert auch andere.", en: "He who respects himself also respects others.", es: "Quien se respeta a sí mismo también respeta a los demás.", author: "Unbekannt" },
  { id: 290, de: "Die Energie, die du in dich investierst, kehrt zu dir zurück.", en: "The energy you invest in yourself returns to you.", es: "La energía que inviertes en ti mismo regresa a ti.", author: "Unbekannt" },
  { id: 291, de: "Mach das Beste aus dem, was du hast, wo du bist.", en: "Do what you can, with what you have, where you are.", es: "Haz lo que puedas, con lo que tienes, donde estés.", author: "Theodore Roosevelt" },
  { id: 292, de: "Dein größter Feind bist nicht die anderen – du bist es selbst.", en: "Your greatest enemy is not others – it is yourself.", es: "Tu mayor enemigo no son los demás: eres tú mismo.", author: "Unbekannt" },
  { id: 293, de: "Sei der Anker in deinem eigenen Sturm.", en: "Be the anchor in your own storm.", es: "Sé el ancla en tu propia tormenta.", author: "Unbekannt" },
  { id: 294, de: "Übe täglich Mitgefühl – mit anderen und mit dir selbst.", en: "Practice compassion daily – with others and with yourself.", es: "Practica la compasión a diario: con los demás y contigo mismo.", author: "Unbekannt" },
  { id: 295, de: "Wahre Stärke zeigt sich in der Fähigkeit, sanft zu sein.", en: "True strength shows itself in the ability to be gentle.", es: "La verdadera fortaleza se muestra en la capacidad de ser amable.", author: "Unbekannt" },
  { id: 296, de: "Das Leben belohnt diejenigen, die täglich auftauchen.", en: "Life rewards those who show up every day.", es: "La vida recompensa a quienes se presentan cada día.", author: "Unbekannt" },
  { id: 297, de: "Tue es lieber schlecht als gar nicht.", en: "Do it imperfectly rather than not at all.", es: "Hazlo imperfectamente antes que no hacerlo.", author: "Unbekannt" },
  { id: 298, de: "Mach weiter. Du bist näher, als du denkst.", en: "Keep going. You are closer than you think.", es: "Sigue adelante. Estás más cerca de lo que crees.", author: "Unbekannt" },
  { id: 299, de: "Ein Tropfen Tun ist mehr wert als ein Ozean an Denken.", en: "A drop of doing is worth more than an ocean of thinking.", es: "Una gota de acción vale más que un océano de pensamiento.", author: "Friedrich Schiller" },
  { id: 300, de: "Nichts Großes wurde je ohne Beharrlichkeit vollbracht.", en: "Nothing great was ever accomplished without perseverance.", es: "Nada grande se logró jamás sin perseverancia.", author: "Unbekannt" },
];
